referenceSolutions.javascript:
export function solve(value, path, fallback) {
  let current = value;
  for (const key of path) {
    if (current === null || typeof current !== "object" || !Object.hasOwn(current, key))
      return fallback;
    current = current[key];
  }
  return current;
}

